solution.javascript:
function rapportAteliers(releves, n) {
  const ateliers = new Map();
  for (const r of releves) {
    if (r.defauts > r.jouets) {
      continue;
    }
    if (!ateliers.has(r.atelier)) {
      ateliers.set(r.atelier, { nom: r.atelier, total: 0, defauts: 0, lutins: new Map() });
    }
    const a = ateliers.get(r.atelier);
    const net = r.jouets - r.defauts;
    a.total += net;
    a.defauts += r.defauts;
    a.lutins.set(r.lutin, (a.lutins.get(r.lutin) || 0) + net);
  }
  const rapport = [];
  for (const a of ateliers.values()) {
    let meilleur = null;
    for (const [lutin, score] of a.lutins) {
      if (meilleur === null || score > a.lutins.get(meilleur) || (score === a.lutins.get(meilleur) && lutin < meilleur)) {
        meilleur = lutin;
      }
    }
    rapport.push({ nom: a.nom, total: a.total, defauts: a.defauts, meilleur: meilleur });
  }
  rapport.sort((x, y) => {
    if (x.total !== y.total) return y.total - x.total;
    if (x.defauts !== y.defauts) return x.defauts - y.defauts;
    return x.nom < y.nom ? -1 : 1;
  });
  return rapport.slice(0, n).map((a) => ({ atelier: a.nom, total: a.total, meilleur: a.meilleur }));
}

solution.python:
def rapport_ateliers(releves, n):
    ateliers = {}
    for r in releves:
        if r["defauts"] > r["jouets"]:
            continue
        if r["atelier"] not in ateliers:
            ateliers[r["atelier"]] = {"nom": r["atelier"], "total": 0, "defauts": 0, "lutins": {}}
        a = ateliers[r["atelier"]]
        net = r["jouets"] - r["defauts"]
        a["total"] += net
        a["defauts"] += r["defauts"]
        a["lutins"][r["lutin"]] = a["lutins"].get(r["lutin"], 0) + net
    rapport = []
    for a in ateliers.values():
        meilleur = None
        for lutin, score in a["lutins"].items():
            if meilleur is None or score > a["lutins"][meilleur] or (score == a["lutins"][meilleur] and lutin < meilleur):
                meilleur = lutin
        rapport.append({"nom": a["nom"], "total": a["total"], "defauts": a["defauts"], "meilleur": meilleur})
    rapport.sort(key=lambda a: (-a["total"], a["defauts"], a["nom"]))
    return [{"atelier": a["nom"], "total": a["total"], "meilleur": a["meilleur"]} for a in rapport[:n]]

